var i=`brooks-s-law`;var o=105;var a={en:[{id:`T105-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Brooks's Law`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`The Pareto principle is a heuristic that a minority of causes often account for a majority of outcomes.`},{id:`B`,text:`Conway's Law observes that system designs tend to reflect the communication structures of the organizations creating them.`},{id:`C`,text:`Brooks's Law warns that adding people to a late software project may make it later because onboarding and communication cost time.`},{id:`D`,text:`The Theory of Constraints holds that overall throughput is limited by a small number of bottlenecks.`}]},{id:`T105-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Brooks's Law`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Identify the current constraint, exploit it efficiently, subordinate upstream work to its capacity, elevate capacity when justified and repeat as bottlenecks move.`},{id:`B`,text:`Estimate coordination paths, module separability and onboarding capacity before scaling a team.`},{id:`C`,text:`Estimate upfront effort, ongoing operations, avoided incidents, delivery acceleration and opportunity cost.`},{id:`D`,text:`Compare required customization, vendor reliability, security/compliance, integration effort, exit costs, data ownership and long-term support.`}]},{id:`T105-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`A delayed release blocked by one complex payment integration will not necessarily accelerate by assigning five unfamiliar developers to that one module.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`Independent test automation may be more parallelizable.`},{id:`B`,text:`Factor in support, edge cases and reliability of the automation.`},{id:`C`,text:`Validate against severity, not just frequency.`},{id:`D`,text:`It can define growth signals for reconsideration.`}]},{id:`T105-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Brooks's Law`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`The law is contextual, not an excuse to understaff a project.`},{id:`B`,text:`Amdahl assumes a fixed workload and idealized parallel execution; real workloads can grow and require Gustafson-style scaling analysis.`},{id:`C`,text:`An ADR should not be a lengthy design specification or a way to rubber-stamp decisions after implementation.`},{id:`D`,text:`Conway's Law is a tendency, not a deterministic theorem.`}]},{id:`T105-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`It highlights constraints on parallelizing knowledge work.`}]}]},{id:`T105-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`Adding developers to a late project always reduces remaining delivery time.`}]}]},{id:`T105-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Strong boundaries, tooling and mentoring can reduce coordination overhead; measure throughput and rework rather than headcount.`}]}]},{id:`T105-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Brooks's Law`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Improving any non-bottleneck stage always increases end-to-end throughput.`},{id:`B`,text:`Estimate coordination paths, module separability and onboarding capacity before scaling a team.`},{id:`C`,text:`Brooks's Law warns that adding people to a late software project may make it later because onboarding and communication cost time.`},{id:`D`,text:`Onboarding and coordination have zero impact on delivery throughput.`}]},{id:`T105-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Brooks's Law`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Strong boundaries, tooling and mentoring can reduce coordination overhead; measure throughput and rework rather than headcount.`},{id:`B`,text:`Independent test automation may be more parallelizable.`},{id:`C`,text:`Adding developers to a late project always reduces remaining delivery time.`},{id:`D`,text:`The vendor's demo proves product fit and future data portability.`}]},{id:`T105-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A delayed release blocked by one complex payment integration will not necessarily accelerate by assigning five unfamiliar developers to that one module.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to propose a staffing and task-splitting plan for a late MVP, separating critical-path work from independent work and explicit onboarding costs.`},{id:`B`,text:`Ask an agent to draft an ADR comparing event-driven and synchronous booking workflows, then have it list evidence that would overturn the selected option.`},{id:`C`,text:`Ask an agent to map team ownership onto a proposed modular architecture, identify dependency bottlenecks and suggest one minimal organizational change.`},{id:`D`,text:`Ask an agent to benchmark sequential and parallel report generation, estimate serial fraction, compare observed speedup with Amdahl's bound and explain overhead.`}]},{id:`T105-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`What work can actually proceed independently without integration bottlenecks?`}]}]},{id:`T105-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A delayed release blocked by one complex payment integration will not necessarily accelerate by assigning five unfamiliar developers to that one module.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Brooks's Law`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T105-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A delayed release blocked by one complex payment integration will not necessarily accelerate by assigning five unfamiliar developers to that one module.`,b:!0},{t:` — propose three checks for `},{t:`Brooks's Law`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T105-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A delayed release blocked by one complex payment integration will not necessarily accelerate by assigning five unfamiliar developers to that one module.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T105-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Brooks's Law`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A delayed release blocked by one complex payment integration will not necessarily accelerate by assigning five unfamiliar developers to that one module.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T105-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Закон Брукса`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Принцип Парето — евристика, за якою невелика частина причин часто створює більшість результатів.`},{id:`B`,text:`Закон Конвея описує тенденцію систем відображати комунікаційну структуру організацій, які їх створюють.`},{id:`C`,text:`Закон Брукса попереджає, що додавання людей до запізнілого проєкту може ще більше затримати його через навчання та комунікацію.`},{id:`D`,text:`Теорія обмежень стверджує, що загальну пропускну здатність обмежує невелика кількість вузьких місць.`}]},{id:`T105-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Закон Брукса`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Визначте обмеження, використайте його ефективно, узгодьте роботу інших ділянок із його потужністю, збільште потужність за потреби та повторіть цикл.`},{id:`B`,text:`Перш ніж збільшувати команду, оцініть канали координації, незалежність модулів і можливість онбордингу.`},{id:`C`,text:`Оцініть стартову працю, експлуатаційні витрати, уникнені інциденти, прискорення релізів і альтернативну вартість.`},{id:`D`,text:`Порівнюйте кастомізацію, надійність постачальника, безпеку й вимоги, інтеграцію, вартість виходу, власність на дані та підтримку.`}]},{id:`T105-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Запізнілий реліз через одну складну платіжну інтеграцію не обов’язково пришвидшиться від п’яти нових людей у тому самому модулі.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Незалежна автоматизація тестів може бути кращою паралельною задачею.`},{id:`B`,text:`Врахуйте підтримку, винятки й надійність процесу.`},{id:`C`,text:`Але враховуйте тяжкість, а не лише частоту.`},{id:`D`,text:`При цьому зафіксувати сигнали для перегляду рішення.`}]},{id:`T105-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Закон Брукса`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Закон контекстний і не виправдовує нестачу людей.`},{id:`B`,text:`Амдал припускає фіксоване завдання й ідеальну паралельність; реальне навантаження може зростати, де корисний аналіз Густафсона.`},{id:`C`,text:`ADR не має бути багатосторінковою специфікацією чи формальністю після реалізації.`},{id:`D`,text:`Закон Конвея — тенденція, а не безумовна теорема.`}]},{id:`T105-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Він показує межі паралелізації інтелектуальної праці.`}]}]},{id:`T105-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Додавання розробників у запізнілий проєкт завжди скорочує термін завершення.`}]}]},{id:`T105-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Чіткі межі, інструменти та менторство зменшують координацію; вимірюйте результат і переробки, а не чисельність.`}]}]},{id:`T105-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Закон Брукса`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Прискорення будь-якого етапу, що не є вузьким місцем, завжди збільшує пропускну здатність.`},{id:`B`,text:`Перш ніж збільшувати команду, оцініть канали координації, незалежність модулів і можливість онбордингу.`},{id:`C`,text:`Закон Брукса попереджає, що додавання людей до запізнілого проєкту може ще більше затримати його через навчання та комунікацію.`},{id:`D`,text:`Онбординг і координація ніяк не впливають на швидкість розробки.`}]},{id:`T105-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Закон Брукса`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Чіткі межі, інструменти та менторство зменшують координацію; вимірюйте результат і переробки, а не чисельність.`},{id:`B`,text:`Незалежна автоматизація тестів може бути кращою паралельною задачею.`},{id:`C`,text:`Додавання розробників у запізнілий проєкт завжди скорочує термін завершення.`},{id:`D`,text:`Демо постачальника доводить придатність продукту та переносимість даних.`}]},{id:`T105-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Запізнілий реліз через одну складну платіжну інтеграцію не обов’язково пришвидшиться від п’яти нових людей у тому самому модулі.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента запропонувати розподіл людей і задач для запізнілого MVP, відділивши критичний шлях від паралельних робіт і вартості онбордингу.`},{id:`B`,text:`Попросіть агента підготувати ADR про синхронний чи подієвий процес бронювання та перелічити докази для перегляду вибору.`},{id:`C`,text:`Попросіть агента накласти власність команд на модульну архітектуру, знайти вузькі місця залежностей і запропонувати одну мінімальну організаційну зміну.`},{id:`D`,text:`Попросіть агента заміряти послідовне й паралельне формування звіту, оцінити послідовну частку, зіставити результат із законом Амдала та пояснити накладні витрати.`}]},{id:`T105-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Які задачі реально виконуються паралельно без вузького місця інтеграції?`}]}]},{id:`T105-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Запізнілий реліз через одну складну платіжну інтеграцію не обов’язково пришвидшиться від п’яти нових людей у тому самому модулі.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Закон Брукса`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T105-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Запізнілий реліз через одну складну платіжну інтеграцію не обов’язково пришвидшиться від п’яти нових людей у тому самому модулі.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Закон Брукса`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T105-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Запізнілий реліз через одну складну платіжну інтеграцію не обов’язково пришвидшиться від п’яти нових людей у тому самому модулі.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T105-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Закон Брукса`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Запізнілий реліз через одну складну платіжну інтеграцію не обов’язково пришвидшиться від п’яти нових людей у тому самому модулі.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var n={slug:i,topicId:105,questions:a};export{n as default,a as questions,i as slug,o as topicId};